<form method="post" data-confirm="Diesen <?= $singular ?> bei ISPConfig löschen? Enthaltene Daten können dabei dauerhaft verloren gehen."><?= csrf() ?><input type="hidden" name="action" value="hosting_delete"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="child_id" value="<?= (int)$child['id'] ?>"><button class="text-button"><?= $singular ?> löschen</button></form>
<?php else: ?><p class="small muted">Bitte den Support kontaktieren, bevor dieser Zugang erneut eingerichtet wird.</p><?php endif ?></article><?php endforeach ?>
