<?php if($kind==='mail'): ?><label class="field"><span>Anzeigename (optional)</span><input name="display_name" maxlength="100" placeholder="z. B. Kundenservice"></label><label class="field"><span>Postfachspeicher in MB</span><input name="quota_mb" type="number" min="1" max="<?= (int)$service['meta']['limits']['mail_quota_mb'] ?>" value="<?= (int)$service['meta']['limits']['mail_quota_mb'] ?>" required></label><?php endif ?>
